-- The Swiss postal-code ↔ locality list, from geonames.org (CC BY 4.0), with the
-- distribution-district suffixes ("Lausanne 10") folded into the locality itself.
--
-- It is *data*, not schema, and it ships as a migration because that is the only
-- step the deploy pipeline runs on its own — `npm run db:seed` is a first-install
-- command, so anything left to it would never reach a running box.
--
-- Cities are proposals, never constraints: the app also writes back any pair a
-- user actually saves, so this list is a starting point, not a closed world.
-- ON CONFLICT keeps that write-back and a re-run from colliding.
